def content():
 p=[]
 p.append(page('森林邮局投递谜案',text('雨水弄乱了邮件。帮助小鹿诺莉修复模糊的包裹标签，完成一趟有依据的纸上投递。'),special('cover'),box('五关，一趟完整投递','分拣六件邮件 → 修复标签 → 装上午邮袋 → 询问住户 → 核验签收。每组2至6名玩家，另有成人主持；7至12人准备两套独立完整材料，分成两个均衡小组。'),text('铅笔、橡皮、纸张和桌面即可。剪刀由成人使用；只用虚构姓名和地址，无需真实邮件或户外投递。')))
 p.append(page('我们的邮局分工',text('第1至4关结束后轮换任务。两三人合并任务，五六人设置搭档；每人都要摆放、询问或解释一次。成人是主持人，不算玩家。第四关改用第14页的临时安排。'),special('jobs'),text('角色卡可剪下，也可整页保留、指认当前任务。')))
 p.append(page('邮局进度记录',text('放在桌子中央。第一关记分拣结果；后面只标记成人核准，不重复抄写标签、交接单和访谈内容。允许口述或由成人代写。'),special('progress'),text('小队名（虚构）：________________。一次只要一条提示，尝试后再要下一条。')))
 p.append(page('先学会怎样查线索',box('另一个包裹的方法示例','示例Q42的线索说：与留存信件同片区，门牌比它大1。示例信写“阳光公园／8号”，所以查到阳光公园、9号。每个字段分别找依据。这组名称、编号和数字都不是正式谜题答案。'),box('每个发现只写在原始表格上','修复地址写标签；装袋顺序写交接单；住户回答写访谈表。进度表只跟踪核准。最后展示这些原件，不再抄一遍答案。'),box('指认和口述也算完成','可以指向图案、描述特征或画出来，不必会写它的名称。搭档或成人可按你的话记录。每关完成先展示原件，成人核准后再领下一关。')))
 def task(i):return page('第'+str(i+1)+'关／'+TITLES[i],box('故事／可朗读',STORIES[i]),box('摆到桌面上',PROPS[i]),*[text(str(j+1)+'. '+v) for j,v in enumerate(STEPS[i])],box('先停一下','展示原始依据，由成人核准、标记进度后再领取下一关。'))
 p.append(task(0))
 p.append(page('邮件分拣台',box('必须按这个顺序检查','1. 封口破损，一律暂缓处理，地址清楚也一样。<br/>2. 封口完整、地址模糊或缺失，放待修复。<br/>3. 封口完整、地址清楚，放可投递。'),special('sort'),text('邮件放在框内或框旁，不粘贴；后面还要用这些原件。分拣台整页保留。')))
 p.append(page('六件森林邮件',text('只剪六个外侧虚线框。地址旁的线条表示清楚或被雨水弄模糊；锯齿表示封口破损，文字同时说明状态。P17的图案封口是后续线索。六件都要保留。'),special('mail')))
 p.append(task(1))
 p.append(page('淋湿标签的四条线索',text('沿外侧虚线剪四张。先匹配包裹编号，再用留存邮件查答案。三张属于P17，一张属于P18。'),special('clues'),text('把三张有效线索分别对应到片区、门牌和封口标记。')))
 p.append(page('复写底稿与新标签',box('P17／模糊的复写底稿','片区名以“树”字结尾；门牌是双数；封口标记模糊。底稿只用于检查推理，不能直接抄出全部答案。收件住户不明，等询问后再填。'),special('label'),text('成人核准第二关后，只剪标签外框。复写底稿保留整张。让标签始终与P17放在一起。')))
 p.append(task(2))
 p.append(page('上午邮袋与交接单',box('装袋规则','只装蓝树片区、上午投递的邮件。共两个位置。符合条件的优先件放在普通件前。不同片区、下午件、暂缓件和仍待修复的邮件留在台上。'),special('bag'),box('留在分拣台','不同片区或时间：______　暂缓：______　仍待修复：______'),box('投递交接单／出发前填写一次','蓝树／上午　第1格：______　第2格：______<br/>投递员虚构记号：______　核验员：______')))
 p.append(task(3))
 p.append(page('问完三户再决定',box('谁扮演住户？','选一名孩子当投递员。两人：另一名孩子演一户，成人演两户；三人：另两名孩子各演一户，成人演第三户。四至六人：三名孩子各演一户，多出的孩子核验或记录。搭档或成人帮助记录。临时替代四种常规任务，本关结束再恢复轮换。'),box('每户都问这三个问题','你在等信还是包裹？编号是什么？封口是什么标记？<br/>三户都住蓝树院落4号。地址只能带你到院落；必须比较种类、编号和标记，不能只凭门牌选收件人。'),special('notes'),text('记录全部三户说出的内容，再与原包裹和标签比较。确认后才补标签的收件人，允许指认或口述。')))
 p.append(page('私密住户卡与纸章',text('仅供成人准备：剪三张住户卡，把下半张回答向后折。不要把未折叠整页给投递员。扮演者看私密背面，投递员只看正面。纸章由成人保管到第五关。'),special('actors'),text('投递员问每户的邮件种类、编号与封口标记。扮演者只按自己的卡回答，被问一项才回答一项。')))
 p.append(task(4))
 p.append(page('投递签收板',box('展示原件，不再抄一遍','展示原包裹及编号、封口图案；展示第10页修复标签。<br/>展示实际邮袋及第12页原交接单。<br/>展示第14页三户访谈记录与匹配住户卡。<br/>成人先核对原件，再接受签名和纸章。'),special('delivery'),text('无需真实姓名、住址、信箱或奖品。')))
 p.append(page('我们的邮局纪念页',text('完整结局由成人保管，签收核准后才能听。此页不含答案，可按需填写。'),box('留下一次合作的记忆','我摆放、询问或核验的一件事：________________<br/><br/>帮助过我们的一项依据：________________'),text('在下面画出你们的邮局，不要抄私密卡上的答案。'),('lines',2),text('重玩时轮换分工；谜题答案不变，成人先把所有填写处重置。')))
 g=[]
 def guide(title,*v):return page(title,*[text(s) for s in v],intro='成人私用／与玩家材料分开保管')
 g.append(guide('主持森林邮局游戏','玩家材料18页，成人指南17页。每组2至6名孩子，成人不计入人数。7至12人准备两套独立玩家材料，分成均衡小组。','先读本指南。后续各关材料盖住，成人第16页完整结局保密。玩家第18页只是空白纪念页。','准备普通纸、铅笔、橡皮、桌面和成人使用的剪刀。无需真实邮件、地址、信封、墨水、胶水、外出路线或购买奖品。','朗读本关故事，让玩家操作，独立核验实际原件；卡住时一次给一条提示。通过后标记进度，再发下一关。','允许指认、画图和口述代写。按推理与图形匹配验收，不额外考词汇、字迹或拼写。'))
 g.append(guide('打印、裁剪与分关发放','选择A4或US Letter，单面、实际大小／100%打印；不要混用纸型或分别缩放卡片与底板。','玩家页码：1封面、2角色、3进度、4中性示例；5至7第一关，8至10第二关，11至12第三关，13至15第四关，16至17第五关，18为结局后可选纪念页。','一组玩家材料18张，两组36张。成人指南若打印一份另加17张，合计35或53张；也可在屏幕阅读指南。省封面与纪念页时，印玩家第2至17页，每组16张。','每组19件：4角色、6邮件、4线索、1新标签、3折叠住户卡、1纸章。开局前剪18件，新标签第二关核准后才剪。少剪方式只把4角色整页保留，共15件。','成人预先剪折玩家第15页住户卡，回答折在背面；不给投递员未折叠的整页。住户卡留到第四关，纸章保管到最后核验。','开局只发玩家第1至4页和第一关第5至7页。整张保留分拣台、进度、复写底稿、邮袋／交接单与签收板；六件邮件一直保留。后续按8至10、11至12、13至15、16至17发放。'))
 g.append(guide('按人数轮换任务','两人：分拣员兼投递员；标签修复员兼核验员。第1至4关后交换这两组任务。','三人：分拣员、投递员、标签修复员兼核验员。第1至4关后顺次轮换三组任务。四人：各一种，第1至4关后顺时针传卡。','五个座位依次是分拣、标签、投递A、投递B、核验。六个座位依次是分拣A、分拣B、标签、投递A、投递B、核验。搭档共用角色卡，同一关内交换操作与检查；关后每人向前移一座。','第四关先按成人第4页、玩家第14页改用住户扮演安排，结束再恢复轮换。人人可讨论、帮忙，不淘汰玩家。'))
 g.append(guide('安排三位私密住户','一名孩子当投递员。两人时，另一人演一户，成人演两户；三人时，另两名孩子各演一户，成人演第三户；四至六人时，三名孩子各演一户，多出的核验或记录。成人可代写。','每个扮演者只拿自己的折叠卡，正面对投递员，私密背面对自己。成人演多户时一次拿一张，先说自己现在是哪户。','投递员逐户询问种类、编号、标记；被问哪项，只答哪项。三户都问完并记录，才能选择。共同院落地址是有意安排，不能用来区分住户。','不剪纸时，玩家第15页不展示给投递员。成人私用第12页的三组事实，依次报住户名并回答；孩子仍负责提问、比较、解释，无需自己偷看答案。','最后签收时，确认住户复述自己的编号和标记，再画虚构签名。成人仍要独立核对全部原件。'))
 starts=[5,8,11,13,16]
 for i in range(5):
  g.append(page('第'+str(i+1)+'关／主持操作',box('摆放材料',PROPS[i]),box('可朗读故事',STORIES[i]),text('带玩家读第'+str(starts[i])+'页。下面是引导动作，下一页私用答案不要朗读给玩家。'),*[text(str(j+1)+'. '+v) for j,v in enumerate(STEPS[i])]))
  g.append(page('第'+str(i+1)+'关／私用核验',box('全部核对后才通过',CHECKS[i]),box('有错怎样处理','指出第一条不符合的规则或依据，让小队改好再展示，不重开整场。保留已经正确的工作。'),text('核准后才标记对应进度行。每个发现保留在原标签、交接单或访谈表，不再重复抄写。'),box('通过后才朗读／发材料',TRANSITIONS[i])))
 g.append(guide('分级提示／一次只给一条','第一关：先检查哪种状态？→封口破损优先暂缓。→A、D可投递，B、F待修复，C、E暂缓。','第二关：先匹配包裹编号。→A给片区和要加1的门牌，B给图案。→蓝树／4／橡果，收件人暂空。','第三关：同时看片区和时间。→只装可投递或修好的邮件，优先件在前。→B在前A在后，其余留台上。','第四关：三户都要问。→比较种类、编号和封口，入口相同不能区分。→猫头鹰家等P17橡果包裹。','第五关：展示原件，不抄一遍。→对照包裹、标签、装袋顺序与访谈。→按成人第14页私用清单逐项核对。','每次提示后都给改正机会。最强提示可以给结果，但不替代分拣、移动、询问、核验和签收。'))
 g.append(page('诺莉送到了包裹',box('成人第16页／私密结局／签收核准后才朗读','诺莉来到蓝树院落4号的猫头鹰家。邻居认出了P17和它的橡果封口，包裹顺利送到了。<br/><br/>“你们整理了整个分拣台，修复了被雨水抹掉的字，装好了邮袋，还先问清楚才交件，”诺莉说，“每一种任务都很重要。”'),text('邀请每个孩子说、指出或展示自己的一次贡献，再按需发玩家第18页空白纪念页。不需要买奖品。')))
 g.append(guide('不剪纸、暂停与重置','不剪纸时邮件、线索保留整页。指认一件，说放哪类或哪个袋格；需要时由成人在旁用铅笔标记。交接单只记两个邮件字母。改位置前先擦旧记号，一件邮件不能同时计入两处。','标签留在原页，放邮袋与签收板旁核验。住户隐私按成人第4页操作，私用第12页回答。纸章不剪时可画章或指向盖章框。替代动作仍遵守原推理和验收条件。','每关核准后都可暂停。把已用原件和表格收在一起，后续材料及住户答案继续保密；从下一关接着玩。','重置时擦掉进度、标签、交接单、访谈、签名和纪念页的填写，清点19件（少剪15件），折好住户卡，纸章收回成人处。表格需要时重印；不要擦印好的邮件依据。','黑白打印也能玩，规则依赖文字、编号和线描图，不单靠颜色。谜题答案固定；重玩可换分工、少用提示。'))
 assert len(p)==18 and len(g)==17
 return p,g
